{
     "title": "CSCI-620: Introduction to Big Data",
     "learningObjectives": [
       "Define the core components of the internet protocol suite and explain how they enable reliable data transmission across networks.",
       "Explain how TCP ensures reliable, ordered byte stream delivery and manages flow control and retransmission.",
       "Apply data preparation, visualization, and statistical techniques to explore large datasets in diverse real-world contexts."
     ],
     "beats": [
       {
         "title": "Lesson Title: CSCI-620: Introduction to Big Data",
         "claim": "Big data exploration and management focuses on exploring and managing large datasets generated in the modern world.",
         "example": "Case studies examine urban crime, drug research, census data, social networking, and space exploration.",
         "visualDirection": "Display a slide with the course title and a grid of icons representing the five case study domains (crime, drug research, census, social networking, space exploration).",
         "sourceIds": ["rit-csci-620"]
       },
       {
         "title": "Lesson Title: Lesson 1: Foundations of Big Data",
         "claim": "Prereqs include CSCI-603 or CSCI-605 with a grade of B or better, or CSCI-320 or SWEN-344.",
         "example": "Students must verify their prerequisite status before enrolling in the course.",
         "visualDirection": "Show a checklist graphic with the prerequisite courses listed and a checkbox for each.",
         "sourceIds": ["rit-csci-620"]
       },
       {
         "title": "Lesson Title: Lesson 2: Internet Protocol Suite Overview",
         "claim": "Internet hosts implement layered link, internet, transport, and application functions.",
         "example": "The link layer moves frames across a directly connected network, while IP provides best-effort datagram delivery across interconnected networks.",
         "visualDirection": "Draw a four-layer stack diagram with labels for link, internet, transport, and application layers, pointing to each layer's function.",
         "sourceIds": ["rfc-1122"]
       },
       {
         "title": "Lesson Title: Lesson 3: IP Addressing and Routing",
         "claim": "An IP address identifies an interface for internet-layer delivery, and routing selects a next hop toward a destination.",
         "example": "When a packet is sent, the router examines the IP address to determine the optimal path to the destination interface.",
         "visualDirection": "Illustrate a network diagram with two routers, highlighting the IP address on an interface and an arrow showing the next hop selection process.",
         "sourceIds": ["rfc-1122"]
       },
       {
         "title": "Lesson Title: Lesson 4: Transport Protocol Functions",
         "claim": "Transport protocols add endpoint communication functions above IP, defining how data is exchanged between endpoints.",
         "example": "Application protocols define the meaning of exchanged data, while transport protocols handle the reliable delivery mechanism.",
         "visualDirection": "Show a simplified TCP/IP model with the transport layer positioned above IP, labeled with 'endpoint communication functions' and 'application protocols' above it.",
         "sourceIds": ["rfc-1122"]
       },
       {
         "title": "Lesson Title: Lesson 5: TCP Reliability and Byte Streams",
         "claim": "TCP provides a reliable, ordered byte stream between endpoints, ensuring data integrity during transmission.",
         "example": "Sequence numbers identify positions in that byte stream, allowing the receiver to reconstruct the original data order.",
         "visualDirection": "Display a sequence of numbered packets (1, 2, 3) arriving at a receiver, with a visual indicator showing how sequence numbers restore order.",
         "sourceIds": ["rfc-9293"]
       },
       {
         "title": "Lesson Title: Lesson 6: TCP Acknowledgments and Retransmission",
         "claim": "Acknowledgments report which data has been received, and retransmission recovers data that is presumed lost.",
         "example": "If a packet is lost, the receiver sends an acknowledgment indicating the gap, prompting the sender to retransmit the missing data.",
         "visualDirection": "Create a timeline graphic showing packet transmission, a missing packet, an acknowledgment signal, and a retransmission arrow.",
         "sourceIds": ["rfc-9293"]
       },
       {
         "title": "Lesson Title: Lesson 7: TCP Flow Control and State Management",
         "claim": "Flow control prevents a sender from exceeding the receiver's advertised capacity, and a TCP connection moves through defined protocol states.",
         "example": "Before application data transfer, connection establishment synchronizes endpoint state to ensure both sides are ready.",
         "visualDirection": "Show a state machine diagram with states like 'Establishment', 'Data Transfer', and 'Termination', with arrows indicating transitions.",
         "sourceIds": ["rfc-9293"]
       },
       {
         "title": "Lesson Title: Lesson 8: Data Preparation and Visualization",
         "claim": "Practical techniques used in exploratory data analysis and mining include data preparation and visualization.",
         "example": "Cleaning and organizing raw datasets allows analysts to identify patterns and trends through visual representations.",
         "visualDirection": "Present a before-and-after comparison of a messy dataset and a cleaned, visualized chart (e.g., bar graph or scatter plot).",
         "sourceIds": ["rit-csci-620"]
       },
       {
         "title": "Lesson Title: Lesson 9: Statistics and Grouping/Prediction Techniques",
         "claim": "Statistics for understanding data, and grouping and prediction techniques, are essential for analyzing large datasets.",
         "example": "Statistical methods help quantify uncertainty, while grouping and prediction techniques identify clusters and forecast future values.",
         "visualDirection": "Display a split screen showing a statistical summary table on the left and a clustering/prediction model output on the right.",
         "sourceIds": ["rit-csci-620"]
       }
     ]
   }
